insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('quiet-firm-explode','Bottled up ≠ Stood up for ≠ Blew up',1,0,'Anger is a signal that a line was crossed. Bottling it up lets people walk over you, and the anger builds until it bursts. Blowing up hurts people and makes the story about your shouting. Standing up for yourself, clearly and calmly, is the healthy middle.','الغضب إشارة إلى أن حدًّا قد تُجووز. كتمانه يجعل الناس يتجاوزونك ويتراكم حتى ينفجر، والانفجار يؤذي الآخرين ويجعل الحديث عن صراخك لا عمّا فعلوه. أما الدفاع عن نفسك بوضوح وهدوء فهو الوسط الصحي.','''No. Stop. If you take it again, I''ll tell the teacher.'' is standing up for yourself: not bottled up, not blown up.','Psychologists call keeping anger inside ''anger-in'' and letting it out in attacks ''anger-out''; healthy ''anger control'' sits between them (Spielberger, STAXI-2). Assertiveness training teaches the middle way (Alberti & Emmons, Your Perfect Right).',89) on conflict (key) do update set title=excluded.title, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
insert into public.word_difference_parts (diff_key, word_id, explain, explain_ar, position) select 'quiet-firm-explode', (select id from public.words where lang = 'en' and lower(headword) = lower('Bottled up') order by (sense = '') desc limit 1), 'Too quiet: kept it inside; it builds up.', 'كتمه في داخله', 0 on conflict (diff_key, word_id) do update set explain = excluded.explain, explain_ar = excluded.explain_ar, position = excluded.position;
