create temp table nq(k int, h text, m text, t text, who text, work text, role text, status text, src text, note text, tags text[], u int);
insert into nq values
 (2043, 'Anyone can become angry; that is easy. But to be angry with the right person, to the right extent, at the right time, with the right motive, and in the right way, that is not easy.', 'Getting angry is easy. Getting angry well is the hard part: at the right person, as much as the thing deserves, at the right moment, for a good reason, and in a fair way. That is a skill you practise.', 'أيُّ أحدٍ يستطيع أن يغضب، فهذا سهل. أمّا أن تغضب من الشخص المناسب، وبالقدر المناسب، وفي الوقت المناسب، وللسبب المناسب، وبالطريقة المناسبة، فهذا ليس سهلًا.', 'Aristotle', 'Nicomachean Ethics II.9', 'said', 'verified', 'https://www.ellopos.net/elpenor/greek-texts/ancient-greece/aristotle/nicomachean-ethics.asp?pg=32', 'Aristotle (384–322 BC), Nicomachean Ethics, Book II ch. 9 (1109a26–29). W. D. Ross''s translation reads: ''any one can get angry—that is easy—or give or spend money; but to do this to the right person, to the right extent, at the right time, with the right motive, and in the right way, that is not for every one, nor is it easy''. The popular wording shortens it to anger.', array['Saying','⇄ Calm vs. angry: calm']::text[], 15),
 (2044, 'Those who are not angry at the things they should be angry at are thought to be fools; to put up with being insulted, and to let your friends be insulted, is slavish.', 'Never getting angry is not a good thing either. If someone is hurting you or your friends and you never stand up to them, you are letting them walk over you. Feel the anger and use it to set a fair line.', 'مَن لا يغضب ممّا يستحق الغضب يُعدّ أحمق، واحتمال الإهانة لنفسك ولأصدقائك ذُلّ.', 'Aristotle', 'Nicomachean Ethics IV.5', 'said', 'verified', 'https://www.ellopos.net/elpenor/greek-texts/ancient-greece/aristotle/nicomachean-ethics.asp?pg=67', 'Aristotle, Nicomachean Ethics, Book IV ch. 5 (1126a3–8), on ''good temper'', the mean between irascibility and inirascibility. W. D. Ross: ''For those who are not angry at the things they should be angry at are thought to be fools … since he does not get angry, he is thought unlikely to defend himself; and to endure being insulted and put up with insult to one''s friends is slavish.''', array['Saying','⇄ Brave vs. scared: brave']::text[], 15);
insert into public.words (lang, headword, sense, meaning, example, translation, syllables, pronunciation, emoji, audio_url, author, tags, owner_id)
select 'en', h, '', m, '', t, '', '', '💬', '', who || ' · ' || work, tags, (select p.id from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com')
from nq on conflict (lang, lower(headword), sense) do nothing;
update public.words w set meaning = nq.m, translation = nq.t, author = nq.who || ' · ' || nq.work, tags = (select array(select distinct x from unnest(w.tags || nq.tags) x order by x))
  from nq where w.lang = 'en' and w.sense = '' and lower(w.headword) = lower(nq.h);
insert into public.set_entries (id, set_id, position, kind, unit, also_units, word_id)
select ('00000000-0000-4000-8000-' || lpad(to_hex(nq.k), 8, '0') || '9007')::uuid, '00000000-0000-4000-8000-000000009007', nq.k, 'term', nq.u, '{}', w.id
from nq join public.words w on w.lang = 'en' and w.sense = '' and lower(w.headword) = lower(nq.h)
on conflict (id) do nothing;
insert into public.people (name, kind) select distinct who, 'person' from nq on conflict do nothing;
update public.people set born = '384 BC', died = '322 BC', nationality = 'Ancient Greece', known_for = 'Greek philosopher; wrote the Nicomachean Ethics on virtue and character', emoji = '🏛️' where name = 'Aristotle' and coalesce(born, '') = '';
delete from public.quote_people l using nq, public.words w where w.lang = 'en' and lower(w.headword) = lower(nq.h) and l.word_id = w.id;
insert into public.quote_people (word_id, person_id, role, status, work, source_url, note, checked_at)
select w.id, p.id, nq.role, nq.status, nq.work, nq.src, nq.note, now()
from nq join public.words w on w.lang = 'en' and w.sense = '' and lower(w.headword) = lower(nq.h)
        join public.people p on lower(btrim(p.name)) = lower(nq.who)
on conflict do nothing;
insert into public.advice (target_type, target_key, word_id, position)
select v.t, v.k, w.id, v.p from (values
 ('condition','healthy_anger',2043,0), ('condition','healthy_anger',2044,1), ('trait','temper',2043,0), ('trait','temper',2044,1),
 ('trait','assertive',2044,1), ('sign','yells_often',2043,0), ('sign','snaps_often',2043,0)
) as v(t, k, n, p) join nq on nq.k = v.n join public.words w on w.lang = 'en' and w.sense = '' and lower(w.headword) = lower(nq.h)
on conflict (target_type, target_key, word_id) do update set position = excluded.position;
drop table nq;
select (select count(*) from public.words where exists (select 1 from unnest(tags) t where t like '📶 Too quiet ⇄ Violent (one moment)%')) as two_sided_meter, (select count(*) from public.words where exists (select 1 from unnest(tags) t where t like '📶 Calm → Violent (one moment)%')) as old_meter_left, (select count(*) from public.conditions where key = 'healthy_anger') as idea, (select count(*) from public.advice a join public.set_entries e on e.word_id = a.word_id where e.set_id = '00000000-0000-4000-8000-000000009007' and e.position in (2043, 2044)) as advice;
